// Native Rust Notch is an authoring command; every size must be regenerated by
// Rust after the edit. This module only plans the operation and never commits.
const SIZES=['XS','S','M','L','XL','XXL']
const fail=reason=>({ok:false,reason,nativeCommitted:false,manufacturingApproved:false})
const finite=n=>typeof n==='number'&&Number.isFinite(n)
const plain=x=>x!==null&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b)

/** Prepare a physical notch for Rust `command` {kind:'Notch',panel,edge,t,depth_m}.
 * Caller must use a real native session, regenerate the six-size grade catalog,
 * verify/save it and inspect a new revision before displaying success.
 */
export function planOptitexNativeGradeNotch20261027({project,sourceRevision,sourceSnapshot,panelId,edgeId,t,depthMm}={}){
 try{
  if(!plain(project)||!plain(project.template)||!Number.isSafeInteger(sourceRevision)||sourceRevision<0||
   !plain(sourceSnapshot)||sourceSnapshot.revision!==sourceRevision||!same(sourceSnapshot.template,project.template))
   return fail('Saved native project must match authenticated source state.current revision and template')
  const run=project.grade_run
  if(!plain(run)||run.schemaVersion!==1||!same(run.sizes,SIZES)||run.baseSize!=='M'||
   !same(run.baseTemplate,project.template)||!Array.isArray(run.gradedTemplates)||run.gradedTemplates.length!==6)
   return fail('Require a fresh persisted Rust six-size grading catalog')
  if(typeof panelId!=='string'||!panelId||typeof edgeId!=='string'||!edgeId||!finite(t)||t<=0||t>=1||
   !finite(depthMm)||depthMm<=0||depthMm>100)
   return fail('Select a named edge, interior fraction and positive physical depth (mm)')
  const proof=[]
  for(let i=0;i<SIZES.length;i++){
   const template=run.gradedTemplates[i]
   if(!plain(template)||!Array.isArray(template.panels))return fail(`Missing Rust graded template for ${SIZES[i]}`)
   const matches=template.panels.filter(p=>p?.id===panelId)
   if(matches.length!==1||!plain(matches[0].polygon))return fail(`Panel missing or ambiguous in ${SIZES[i]}`)
   const polygon=matches[0].polygon
   if(!Array.isArray(polygon.edges)||!polygon.edges.includes(edgeId)||new Set(polygon.edges).size!==polygon.edges.length)
    return fail(`Named native edge missing or ambiguous in ${SIZES[i]}`)
   const notches=polygon.notches??{}
   if(!plain(notches)||Object.values(notches).some(v=>!Array.isArray(v)))return fail(`Invalid native notch inventory in ${SIZES[i]}`)
   if((notches[edgeId]??[]).some(n=>!finite(n?.t)||!finite(n?.depth_m)||Math.abs(n.t-t)<1e-8))
    return fail(`Duplicate or malformed notch station in ${SIZES[i]}`)
   if(!Array.isArray(polygon.points)||polygon.points.length<3||polygon.edges.length!==polygon.points.length)
    return fail(`Invalid native edge topology in ${SIZES[i]}`)
   proof.push({size:SIZES[i],panelId,edgeId,existingCount:(notches[edgeId]??[]).length})
  }
  return {ok:true,nativeCommitted:false,manufacturingApproved:false,sourceRevision,
   command:{kind:'Notch',panel:panelId,edge:edgeId,t,depth_m:depthMm/1000},
   sizes:[...SIZES],preflight:proof,
   requiredPostconditions:['native command accepted','source revision incremented',
    'six graded templates regenerated and saved at new source revision',
    'each graded template has exact notch fraction and depth',
    'native production cutlines and sewing QA pass'],
   notice:'Native notch transaction prepared. No notch was changed or saved.'}
 }catch(e){return fail(String(e?.message||e))}
}

/** Check real saved Rust output after the caller has committed and regenerated. */
export function verifyOptitexNativeGradeNotch20261027({plan,project,afterRevision,afterSnapshot}={}){
 if(!plan?.ok||!plain(project)||!Number.isSafeInteger(afterRevision)||afterRevision<=plan.sourceRevision||
  !plain(afterSnapshot)||afterSnapshot.revision!==afterRevision||!same(afterSnapshot.template,project.template))
  return fail('Native revision has not advanced after the notch transaction')
 const run=project.grade_run
 if(!plain(run)||run.schemaVersion!==1||!same(run.sizes,SIZES)||!same(run.baseTemplate,project.template)||
    !Array.isArray(run.gradedTemplates)||run.gradedTemplates.length!==6)
  return fail('Native six-size grade catalog was not regenerated and saved')
 const basePanels=project.template.panels
 const baseMatches=Array.isArray(basePanels)?basePanels.filter(p=>p?.id===plan.command.panel):[]
 const baseMarks=baseMatches.length===1?baseMatches[0].polygon?.notches?.[plan.command.edge]:null
 if(!Array.isArray(baseMarks)||baseMarks.filter(n=>Math.abs(n?.t-plan.command.t)<1e-8&&
   Math.abs(n?.depth_m-plan.command.depth_m)<1e-9).length!==1)
  return fail('Committed native source polygon is missing the exact physical notch')
 for(let i=0;i<SIZES.length;i++){
  const panels=run.gradedTemplates[i]?.panels
  const matching=Array.isArray(panels)?panels.filter(p=>p?.id===plan.command.panel):[]
  const marks=matching.length===1?matching[0].polygon?.notches?.[plan.command.edge]:null
  if(!Array.isArray(marks)||marks.filter(n=>Math.abs(n?.t-plan.command.t)<1e-8&&
   Math.abs(n?.depth_m-plan.command.depth_m)<1e-9).length!==1)
   return fail(`Saved Rust grade notch is missing, duplicated, or changed in ${SIZES[i]}`)
 }
 return {ok:true,nativeCommitted:true,manufacturingApproved:false,sourceRevision:plan.sourceRevision,
  committedRevision:afterRevision,sizes:[...SIZES],notice:'Native saved notch verified in all six graded templates; manufacturing approval remains separate'}
}
